function validate([text]) {
  if (typeof text !== 'string' || text.length < 1 || text.length > 100000) return 'text needs 1 to 10^5 characters.';
  if (!/^[A-Z][a-z]*( [a-z]+)*$/.test(text)) return 'text starts with an uppercase letter, then has lowercase words separated by single spaces.';
  return null;
}

