function arrangeWords(text) {
  const lower = text.toLowerCase();
  const words = lower.split(" ");
  words.sort((a, b) => a.length - b.length);
  const first = words[0];
  words[0] = first[0].toUpperCase() + first.slice(1);
  const sentence = words.join(" ");
  return sentence;
}

