function arrangeWords(text) {
  // Collect the words of length 1, then of length 2, and so on, each time scanning the sentence from the left.
  const original = text.split(" ").map(w => w.toLowerCase());
  let longest = 0;
  for (const w of original) longest = Math.max(longest, w.length);
  const result = [];
  for (let len = 1; len <= longest; len++)
    for (const w of original) if (w.length === len) result.push(w);
  let out = result.join(" ");
  out = out.charAt(0).toUpperCase() + out.substring(1);
  return out;
}

