function generate(rand, size) {
  const letters = size === 'large' && rand() < 0.5 ? 'abcdefghijklmnopqrstuvwxyz' : 'abc';
  const word = (maxLen) => {
    const len = 1 + Math.floor(rand() * maxLen);
    let w = '';
    for (let i = 0; i < len; i++) w += letters[Math.floor(rand() * letters.length)];
    return w;
  };
  const words = [];
  if (size === 'large') {
    const maxLen = [3, 8, 15][Math.floor(rand() * 3)];
    let length = 0;
    while (true) {
      const w = word(maxLen);
      if (length + w.length + 1 > 10000) break;
      words.push(w);
      length += w.length + 1;
    }
  } else {
    const n = 1 + Math.floor(rand() * 7);
    const maxLen = 1 + Math.floor(rand() * 5);
    for (let i = 0; i < n; i++) words.push(word(maxLen));
  }
  const text = words.join(' ');
  return [text[0].toUpperCase() + text.slice(1)];
}
